    {"symbol": "🏛️", "tooltip": "A two-tiered economy is a load-bearing crack in the institutions that must later gate AI deployment."}
  ],
  "claim_sketches": [
    {"claim": "The Accelerationist's own citation — Acemoglu and Restrepo's 2020 finding that the U.S. tax code over-subsidizes machines relative to labor — proves the firm's incentive to displace is already distorted before any policy responds.", "targets": ["AN-3"], "relationship": "extends"},
    {"claim": "A pure cushion funds around that distortion, paying the displaced worker while letting the firm keep externalizing the foreseeable cost of the deployment decision it chose to make.", "targets": [], "relationship": ""},
    {"claim": "A sustained two-tiered economy is the structural condition under which capital owners find repression cheaper than redistribution.", "targets": ["AN-7"], "relationship": "extends"},
    {"claim": "The burden of proof for a structural distributional intervention should scale with the reversibility of the outcome, not with the cleanliness of the estimate.", "targets": [], "relationship": ""},
    {"claim": "Enforceable accountability that is not itself auditable and publicly accountable is just a different concentration wearing a regulator's badge.", "targets": [], "relationship": ""}
  ]
}

